-- POLISH TRANSLATIONS (pl) - FULL TEXTS
INSERT INTO document_translations (document_id, language_code, name, text)
VALUES
    (
        'd1', 'pl', 'Regulamin świadczenia usług telekomunikacyjnych',
        '<h3>I. KORZYŚCI PROMOCJI</h3><ol><li>Obniżone opłaty za usługi telekomunikacyjne w każdym Okresie Rozliczeniowym w Okresie Promocji (przez okres nie dłuższy niż 24 miesiące), tj. nabycie usług telekomunikacyjnych na preferencyjnych warunkach (z rabatem określonym w niniejszym Regulaminie Promocji).</li><li>Obniżone Opłaty Jednorazowe w przypadku aktywacji usług telekomunikacyjnych.</li><li>Otrzymanie dodatkowych rabatów za wyrażenie wszystkich Zgód marketingowych (rabat 5 zł miesięcznie) oraz wyrażenie zgody na e-Fakturę (rabat 5 zł miesięcznie) przyznawanych zgodnie z odrębnym Regulaminem Promocji „Zgody marketingowe/e faktura”.</li></ol><h3>II. DEFINICJE</h3><ol><li>Organizator Promocji – ELCARO Spółka z ograniczoną odpowiedzialnością z siedzibą w Warszawie (03-140), przy ul. Odkrytej 1A, wpisana pod numerem 0000623333 do rejestru przedsiębiorców KRS, prowadzonego przez Sąd Rejonowy dla m. st. Warszawy w Warszawie, XIII Wydział Gospodarczy KRS, której nadano NIP: 5242803567 oraz REGON: 364717322;</li><li>Abonent – nowy klient oraz pełnoletnia osoba fizyczna, która łącznie spełnia następujące warunki:<ol type="a"><li>w okresie 3 (słownie: trzech) miesięcy przed Przystąpieniem do promocji nie był Abonentem Organizatora Promocji w zakresie jakiekolwiek z Usług stacjonarnych,</li><li>nie zalega względem Organizatora Promocji z płatnościami z jakiegokolwiek tytułu,</li><li>przystępuje do Promocji w celach nie związanych z działalnością gospodarczą;</li></ol></li><li>Promocja – kampania promocyjna prowadzona przez Organizatora Promocji pod hasłem „Oferta na bloki_lato 2024”, stanowiąca warunki, zasady nabywania i świadczenia Usług określonych w niniejszym Regulaminie Promocji.</li><li>Korzyści – korzyści o których mowa w pkt. I Regulaminu Promocji;</li><li>Umowa – Umowa o świadczenie Usług przez Organizatora Promocji zawarta na warunkach promocyjnych, na czas określony 24 miesięcy dla usług oferowanych przez Organizatora Promocji w niniejszym Regulaminie Promocji;</li><li>Przystąpienie do promocji – data zawarcia przez Uczestnika Promocji Umowy na warunkach określonych w Umowie oraz w niniejszym Regulaminie Promocji;</li><li>Uczestnik Promocji – Abonent który zawarł Umowę z Organizatorem Promocji;</li><li>Usługa – usługi telekomunikacyjne lub pakiet usług telekomunikacyjnych świadczonych przez Organizatora Promocji na podstawie Umowy.</li><li>Okres rozliczeniowy – okres za który dokonywane są rozliczenia należności Uczestnika Promocji wobec Organizatora Promocji z tytułu świadczenia Usług, rozpoczynający się i kończący we wskazanym przed Organizatora Promocji dniach miesiąca. O ile nie wskazano inaczej okres rozliczeniowy wynosi jeden miesiąc kalendarzowy.</li></ol>'
    ),
    (
        'd3', 'pl', 'Regulamin promocji "Oferta na bloki_lato 2024"',
        '<h3>I. KORZYŚCI PROMOCJI</h3><ol><li>Obniżone opłaty za usługi telekomunikacyjne w każdym Okresie Rozliczeniowym w Okresie Promocji (przez okres nie dłuższy niż 24 miesiące), tj. nabycie usług telekomunikacyjnych na preferencyjnych warunkach (z rabatem określonym w niniejszym Regulaminie Promocji).</li><li>Obniżone Opłaty Jednorazowe w przypadku aktywacji usług telekomunikacyjnych.</li><li>Otrzymanie dodatkowych rabatów za wyrażenie wszystkich Zgód marketingowych (rabat 5 zł miesięcznie) oraz wyrażenie zgody na e-Fakturę (rabat 5 zł miesięcznie) przyznawanych zgodnie z odrębnym Regulaminem Promocji „Zgody marketingowe/e faktura”.</li></ol><h3>II. DEFINICJE</h3><ol><li>Organizator Promocji – ELCARO Spółka z ograniczoną odpowiedzialnością z siedzibą w Warszawie (03-140), przy ul. Odkrytej 1A, wpisana pod numerem 0000623333 do rejestru przedsiębiorców KRS, prowadzonego przez Sąd Rejonowy dla m. st. Warszawy w Warszawie, XIII Wydział Gospodarczy KRS, której nadano NIP: 5242803567 oraz REGON: 364717322;</li><li>Abonent – nowy klient oraz pełnoletnia osoba fizyczna, która łącznie spełnia następujące warunki:<ol type="a"><li>w okresie 3 (słownie: trzech) miesięcy przed Przystąpieniem do promocji nie był Abonentem Organizatora Promocji w zakresie jakiekolwiek z Usług stacjonarnych,</li><li>nie zalega względem Organizatora Promocji z płatnościami z jakiegokolwiek tytułu,</li><li>przystępuje do Promocji w celach nie związanych z działalnością gospodarczą;</li></ol></li><li>Promocja – kampania promocyjna prowadzona przez Organizatora Promocji pod hasłem „Oferta na bloki_lato 2024”, stanowiąca warunki, zasady nabywania i świadczenia Usług określonych w niniejszym Regulaminie Promocji.</li><li>Korzyści – korzyści o których mowa w pkt. I Regulaminu Promocji;</li><li>Umowa – Umowa o świadczenie Usług przez Organizatora Promocji zawarta na warunkach promocyjnych, na czas określony 24 miesięcy dla usług oferowanych przez Organizatora Promocji w niniejszym Regulaminie Promocji;</li><li>Przystąpienie do promocji – data zawarcia przez Uczestnika Promocji Umowy na warunkach określonych w Umowie oraz w niniejszym Regulaminie Promocji;</li><li>Uczestnik Promocji – Abonent który zawarł Umowę z Organizatorem Promocji;</li><li>Usługa – usługi telekomunikacyjne lub pakiet usług telekomunikacyjnych świadczonych przez Organizatora Promocji na podstawie Umowy.</li><li>Okres rozliczeniowy – okres za który dokonywane są rozliczenia należności Uczestnika Promocji wobec Organizatora Promocji z tytułu świadczenia Usług, rozpoczynający się i kończący we wskazanym przed Organizatora Promocji dniach miesiąca. O ile nie wskazano inaczej okres rozliczeniowy wynosi jeden miesiąc kalendarzowy.</li></ol>'
    ),
    (
        'p1', 'pl', 'Polityka prywatności',
        '<h3>Polityka prywatności i wykorzystywania plików cookies</h3><p>Zgodnie z art. 13 ust. 1 i 2 Rozporządzenia Parlamentu Europejskiego i Rady (UE) 2016/679 z dnia 27 kwietnia 2016 r. (RODO) informujemy, że Administratorem Twoich danych osobowych jest ELCARO Sp. z o.o. z siedzibą w Warszawie.</p><h3>Cele i podstawy przetwarzania</h3><p>Twoje dane osobowe przetwarzane będą w celu zawarcia i wykonania umowy o świadczenie usług telekomunikacyjnych (art. 6 ust. 1 lit. b RODO), realizacji obowiązków prawnych ciążących na Administratorze, w tym wystawiania faktur i dokumentów księgowych (art. 6 ust. 1 lit. c RODO), a także w celach wynikających z prawnie uzasadnionych interesów realizowanych przez Administratora, takich jak marketing bezpośredni oraz dochodzenie roszczeń (art. 6 ust. 1 lit. f RODO).</p><h3>Odbiorcy danych i okres przechowywania</h3><p>Twoje dane mogą być przekazywane podmiotom przetwarzającym dane na nasze zlecenie (np. dostawcom systemów IT, podmiotom świadczącym usługi windykacyjne). Dane będą przechowywane przez okres trwania umowy, a po jej zakończeniu przez czas wymagany przepisami prawa (np. podatkowego) oraz do upływu okresu przedawnienia roszczeń.</p><h3>Prawa osoby, której dane dotyczą</h3><p>Posiadasz prawo dostępu do treści swoich danych oraz prawo ich sprostowania, usunięcia, ograniczenia przetwarzania, prawo do przenoszenia danych, prawo wniesienia sprzeciwu, a także prawo do cofnięcia zgody w dowolnym momencie. Przysługuje Ci również prawo wniesienia skargi do Prezesa Urzędu Ochrony Danych Osobowych.</p>'
    ),
    (
        'p2', 'pl', 'Ogólna zgoda marketingowa',
        'Wyrażam zgodę na otrzymywanie od ELCARO Sp. z o.o. z siedzibą w Warszawie, treści marketingowych obejmujących informacje o usługach, produktach, programach i promocjach Spółki, a także prowadzenie badań marketingowych i satysfakcji klienta poprzez połączenia telefoniczne, w tym połączenia z wykorzystaniem automatycznych systemów wywołujących na podany numer telefonu.'
    ),
    (
        'm1', 'pl', 'Zgoda na kontakt mailowy',
        'Wyrażam zgodę na otrzymywanie informacji handlowych drogą elektroniczną, na udostępniony przeze mnie adres e-mail, w rozumieniu ustawy z dnia 18 lipca 2002 r. o świadczeniu usług drogą elektroniczną od ELCARO Sp. z o.o. z siedzibą w Warszawie.'
    ),
    (
        'm2', 'pl', 'Zgoda na kontakt telefoniczny',
        'Wyrażam zgodę na używanie telekomunikacyjnych urządzeń końcowych i automatycznych systemów wywołujących dla celów marketingu bezpośredniego przez ELCARO Sp. z o.o. z siedzibą w Warszawie, zgodnie z art. 172 ustawy z dnia 16 lipca 2004 r. Prawo telekomunikacyjne.'
    ),
    (
        'm3', 'pl', 'Zgoda na profilowanie',
        'Wyrażam zgodę na zautomatyzowane przetwarzanie moich danych osobowych, w tym profilowanie, w celu dostosowania przedstawianej mi oferty handlowej ELCARO Sp. z o.o. do moich osobistych preferencji i zachowań wynikających z historii korzystania z usług telekomunikacyjnych.'
    ),
    (
        't1', 'pl', 'Regulamin rejestracji w eBOK',
        '<h3>Regulamin korzystania z Elektronicznego Biura Obsługi Klienta (eBOK)</h3><h3>I. Postanowienia ogólne</h3><p>Serwis eBOK jest platformą internetową udostępnianą przez ELCARO Sp. z o.o., umożliwiającą Abonentom dostęp do informacji o posiadanych usługach, fakturach, płatnościach oraz umożliwiającą zarządzanie usługami.</p><h3>II. Rejestracja i logowanie</h3><p>1. Do korzystania z eBOK uprawnieni są wyłącznie Abonenci posiadający aktywną umowę z ELCARO.<br>2. Proces rejestracji wymaga weryfikacji tożsamości Abonenta za pomocą jednorazowego kodu PIN wysyłanego na numer telefonu wskazany w Umowie.<br>3. Abonent zobowiązuje się do zachowania poufności swoich danych logowania (loginu i hasła).</p><h3>III. Funkcjonalności</h3><p>Za pośrednictwem eBOK Abonent może w szczególności: weryfikować stan salda, opłacać faktury poprzez zintegrowane systemy płatności online, zgłaszać usterki techniczne, pobierać bilingi oraz modyfikować wyrażone zgody marketingowe. Operator zastrzega sobie prawo do czasowego wyłączania serwisu w celu przeprowadzania prac konserwacyjnych.</p>'
    ),
    (
        's1', 'pl', 'Specyfikacja techniczna usług',
        '<h3>Specyfikacja techniczna świadczonych usług</h3><h3>1. Parametry łącza światłowodowego</h3><p>Usługa dostępu do Internetu realizowana jest w architekturze FTTH (Fiber To The Home). Zapewniamy symetryczne lub asymetryczne przepustowości do 1 Gb/s w zależności od wybranego pakietu. Medium transmisyjnym jest kabel światłowodowy jednomodowy zakończony na urządzeniu ONT (Optical Network Terminal) w lokalu Abonenta.</p><h3>2. Urządzenia dostępowe</h3><p>Sprzęt dostarczany Abonentowi obsługuje najnowsze standardy transmisji bezprzewodowej (Wi-Fi 6 / 802.11ax), zapewniając optymalne pokrycie sygnałem oraz obsługę wielu urządzeń jednocześnie. Urządzenie klienckie posiada minimum 4 porty Gigabit Ethernet dla połączeń przewodowych (LAN).</p><h3>3. Adresacja IP i bezpieczeństwo</h3><p>Abonent otrzymuje dynamicznie przydzielany publiczny lub prywatny adres IPv4 (w zależności od opcji w umowie) oraz wsparcie dla protokołu IPv6. Operator wdraża podstawowe filtry anty-DDoS na urządzeniach brzegowych sieci, chroniąc infrastrukturę przed atakami wolumetrycznymi. Zarządzanie zaporą sieciową (Firewall) po stronie sieci domowej leży w gestii Abonenta.</p>'
    )
    ON CONFLICT (document_id, language_code) DO UPDATE SET text = EXCLUDED.text, name = EXCLUDED.name;

-- ENGLISH TRANSLATIONS (en) - FULL TEXTS
INSERT INTO document_translations (document_id, language_code, name, text)
VALUES
    (
        'd1', 'en', 'Terms and Conditions for the Provision of Telecommunication Services',
        '<h3>I. PROMOTION BENEFITS</h3><ol><li>Reduced fees for telecommunication services in each Billing Period during the Promotion Period (for a period not exceeding 24 months), i.e., the purchase of telecommunication services on preferential terms (with a discount specified in these Promotion Terms).</li><li>Reduced One-time Fees for the activation of telecommunication services.</li><li>Receiving additional discounts for granting all marketing Consents (discount of PLN 5 per month) and granting consent for e-Invoice (discount of PLN 5 per month) granted in accordance with separate Promotion Terms "Marketing Consents / e-invoice".</li></ol><h3>II. DEFINITIONS</h3><ol><li>Promotion Organizer – ELCARO Sp. z o.o. headquartered in Warsaw (03-140), at 1A Odkryta St., registered under number 0000623333 in the register of entrepreneurs.</li><li>Subscriber – a new customer and an adult natural person who meets all of the following conditions:<ol type="a"><li>in the period of 3 months prior to Joining the promotion was not a Subscriber of the Organizer in respect of any stationary Services,</li><li>is not in arrears with payments to the Promotion Organizer under any title,</li><li>joins the Promotion for purposes unrelated to business activity;</li></ol></li><li>Promotion – a promotional campaign run by the Promotion Organizer under the slogan "Block Offer Summer 2024", defining the terms and conditions of purchasing and providing the Services.</li><li>Benefits – benefits referred to in point I of the Promotion Terms;</li><li>Agreement – an Agreement for the provision of Services by the Organizer concluded on promotional terms, for a fixed period of 24 months.</li><li>Joining the promotion – the date of conclusion of the Agreement by the Promotion Participant.</li><li>Promotion Participant – a Subscriber who concluded an Agreement with the Promotion Organizer.</li><li>Service – telecommunications services or a package of telecommunications services provided by the Organizer based on the Agreement.</li><li>Billing period – the period for which the settlements of the Promotion Participant''s dues are made, usually corresponding to one calendar month.</li></ol>'
    ),
    (
        'd3', 'en', 'Promotion Terms "Block Offer Summer 2024"',
        '<h3>I. PROMOTION BENEFITS</h3><ol><li>Reduced fees for telecommunication services in each Billing Period during the Promotion Period (for a period not exceeding 24 months), i.e., the purchase of telecommunication services on preferential terms (with a discount specified in these Promotion Terms).</li><li>Reduced One-time Fees for the activation of telecommunication services.</li><li>Receiving additional discounts for granting all marketing Consents (discount of PLN 5 per month) and granting consent for e-Invoice (discount of PLN 5 per month) granted in accordance with separate Promotion Terms "Marketing Consents / e-invoice".</li></ol><h3>II. DEFINITIONS</h3><ol><li>Promotion Organizer – ELCARO Sp. z o.o. headquartered in Warsaw (03-140), at 1A Odkryta St., registered under number 0000623333 in the register of entrepreneurs.</li><li>Subscriber – a new customer and an adult natural person who meets all of the following conditions:<ol type="a"><li>in the period of 3 months prior to Joining the promotion was not a Subscriber of the Organizer in respect of any stationary Services,</li><li>is not in arrears with payments to the Promotion Organizer under any title,</li><li>joins the Promotion for purposes unrelated to business activity;</li></ol></li><li>Promotion – a promotional campaign run by the Promotion Organizer under the slogan "Block Offer Summer 2024", defining the terms and conditions of purchasing and providing the Services.</li><li>Benefits – benefits referred to in point I of the Promotion Terms;</li><li>Agreement – an Agreement for the provision of Services by the Organizer concluded on promotional terms, for a fixed period of 24 months.</li><li>Joining the promotion – the date of conclusion of the Agreement by the Promotion Participant.</li><li>Promotion Participant – a Subscriber who concluded an Agreement with the Promotion Organizer.</li><li>Service – telecommunications services or a package of telecommunications services provided by the Organizer based on the Agreement.</li><li>Billing period – the period for which the settlements of the Promotion Participant''s dues are made, usually corresponding to one calendar month.</li></ol>'
    ),
    (
        'p1', 'en', 'Privacy Policy',
        '<h3>Privacy and Cookie Policy</h3><p>In accordance with Art. 13 sec. 1 and 2 of the General Data Protection Regulation (GDPR), we inform you that the Controller of your personal data is ELCARO Sp. z o.o. based in Warsaw.</p><h3>Purposes and Basis of Processing</h3><p>Your personal data will be processed for the purpose of concluding and performing the contract for the provision of telecommunications services (Art. 6(1)(b) GDPR), fulfilling legal obligations, including issuing invoices (Art. 6(1)(c) GDPR), and for purposes resulting from legitimate interests, such as direct marketing and pursuing claims (Art. 6(1)(f) GDPR).</p><h3>Data Recipients and Storage Period</h3><p>Your data may be transferred to entities processing data on our behalf (e.g., IT providers, debt collection agencies). Data will be stored for the duration of the contract, and after its termination for the time required by law (e.g., tax law) and until the expiry of the claims limitation period.</p><h3>Data Subject Rights</h3><p>You have the right to access your data and the right to rectify, erase, restrict processing, the right to data portability, the right to object, and the right to withdraw consent at any time. You also have the right to lodge a complaint with the President of the Personal Data Protection Office.</p>'
    ),
    (
        'p2', 'en', 'General Marketing Consent',
        'I agree to receive marketing content from ELCARO Sp. z o.o. based in Warsaw, including information about the Company''s services, products, programs, and promotions, as well as conducting marketing and customer satisfaction research via telephone calls, including calls using automated calling systems to the provided phone number.'
    ),
    (
        'm1', 'en', 'Email Contact Consent',
        'I agree to receive commercial information electronically to the email address I provided, within the meaning of the Act on Rendering Electronic Services, from ELCARO Sp. z o.o. based in Warsaw.'
    ),
    (
        'm2', 'en', 'Phone Contact Consent',
        'I agree to the use of telecommunications terminal equipment and automated calling systems for direct marketing purposes by ELCARO Sp. z o.o. based in Warsaw, in accordance with the Telecommunications Law.'
    ),
    (
        'm3', 'en', 'Profiling Consent',
        'I agree to the automated processing of my personal data, including profiling, in order to tailor the commercial offers of ELCARO Sp. z o.o. to my personal preferences and behaviors resulting from the history of using telecommunications services.'
    ),
    (
        't1', 'en', 'eBOK Registration Regulations',
        '<h3>Regulations for using the Electronic Customer Service Office (eBOK)</h3><h3>I. General Provisions</h3><p>The eBOK service is an internet platform provided by ELCARO Sp. z o.o., enabling Subscribers to access information about their services, invoices, payments, and to manage services.</p><h3>II. Registration and Login</h3><p>1. Only Subscribers with an active contract with ELCARO are entitled to use eBOK.<br>2. The registration process requires verification of the Subscriber''s identity using a one-time PIN code sent to the phone number indicated in the Agreement.<br>3. The Subscriber is obliged to maintain the confidentiality of their login data.</p><h3>III. Functionalities</h3><p>Through eBOK, the Subscriber can in particular: check their balance, pay invoices via integrated online payment systems, report technical faults, download billing statements, and modify granted marketing consents. The Operator reserves the right to temporarily disable the service for maintenance work.</p>'
    ),
    (
        's1', 'en', 'Technical Specification of Services',
        '<h3>Technical Specification of Provided Services</h3><h3>1. Fiber Optic Link Parameters</h3><p>The Internet access service is implemented in the FTTH (Fiber To The Home) architecture. We provide symmetric or asymmetric bandwidths up to 1 Gbps depending on the selected package. The transmission medium is a single-mode fiber optic cable terminated at the ONT (Optical Network Terminal) device at the Subscriber''s premises.</p><h3>2. Access Devices</h3><p>The equipment provided to the Subscriber supports the latest wireless transmission standards (Wi-Fi 6 / 802.11ax), ensuring optimal signal coverage and support for multiple devices simultaneously. The client device has a minimum of 4 Gigabit Ethernet ports for wired connections (LAN).</p><h3>3. IP Addressing and Security</h3><p>The Subscriber receives a dynamically assigned public or private IPv4 address (depending on the contract option) and support for the IPv6 protocol. The Operator implements basic anti-DDoS filters on the network edge devices, protecting the infrastructure from volumetric attacks. Managing the firewall on the home network side is the Subscriber''s responsibility.</p>'
    )
    ON CONFLICT (document_id, language_code) DO UPDATE SET text = EXCLUDED.text, name = EXCLUDED.name;
